node -e "
const tests = [1.005, 1.234, 1.235, 2.005, 0.005, 10.005, 1.004, 1.006];
const fns = {
  eps: (x) => Math.round((x + Number.EPSILON) * 100) / 100,
  eps2: (x) => Math.round(x * 100 + Number.EPSILON) / 100,
  e8: (x) => Math.round(x * 100 + 1e-8) / 100,
  prec: (x) => Math.round(parseFloat((x * 100).toPrecision(12))) / 100,
  fixed: (x) => Math.round(Number((x * 100).toFixed(8))) / 100,
};
for (const [name, fn] of Object.entries(fns)) {
  console.log(name, tests.map(t => fn(t)));
}
"
